import {createSession,respond,firstQuestion,topics} from './engine.mjs';
import {runTests} from './tests.mjs';
const $=id=>document.getElementById(id);let session=createSession(),data=[],ready=false,sound=false,consent=false,recognition=null,listening=false,latest='',epoch=0;
const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
function localVoice(){return window.speechSynthesis?.getVoices().find(v=>v.lang.toLowerCase().startsWith('nl')&&v.localService);}
function speak(text){if(!sound)return;const voice=localVoice();if(!voice){$('status').textContent='Geen lokale Nederlandse stem beschikbaar. Installeer een Nederlandse systeemstem voor spraakuitvoer.';return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='nl-NL';u.voice=voice;u.rate=.96;u.onerror=()=>{$('status').textContent='Voorlezen lukte niet. Probeer geluid opnieuw aan te zetten.';};window.speechSynthesis.speak(u);}
function message(text,user=false){const wrap=document.createElement('div');wrap.className='message'+(user?' user':'');const label=document.createElement('div');label.className='label';label.textContent=user?'Jij':'MinorKompas';const bubble=document.createElement('div');bubble.className='bubble';bubble.textContent=text;wrap.append(label,bubble);$('chat').append(wrap);$('chat').scrollTop=$('chat').scrollHeight;if(!user){latest=text;speak(text);}}
function suggestions(){const choices={study:['HBO-ICT','Verpleegkunde','Bedrijfskunde','Overslaan'],interests:['Cybersecurity','Ondernemen','Creatief ontwerpen','Zorg en herstel','Duurzaamheid','Data-analyse'],direction:['Verdiepen','Verbreden','Allebei'],focus:session.topics[0]==='cyber'?['Organisaties beschermen','Technische beveiliging']:session.topics[0]==='ondernemen'?['Een eigen bedrijf starten','Ondernemen verkennen']:session.topics[0]==='creatief'?['Ideeën bedenken','Ontwerpen maken']:session.topics[0]==='zorg'?['Herstel ondersteunen','Psychische problemen']:session.topics[0]==='duurzaam'?['Klimaat begrijpen','Circulaire organisaties']:['Data analyseren','Betere bedrijfsbeslissingen'],results:['Waarom deze minoren?','Andere interesse','Studieadviseur']};$('suggestions').replaceChildren();for(const c of choices[session.step]||[]){const b=document.createElement('button');b.className='chip';b.textContent=c;b.onclick=()=>submit(c);$('suggestions').append(b);}const idx=['study','interests','direction','focus','results'].indexOf(session.step);[...$('steps').children].forEach((li,i)=>li.className=i===idx?'active':i<idx?'complete':'');$('profileValues').replaceChildren();for(const [label,value]of [['Opleiding',session.study],['Interesses',session.topics.map(k=>topics[k].label).join(', ')],['Richting',session.direction]])if(value){const div=document.createElement('div');const strong=document.createElement('strong');strong.textContent=label+': ';div.append(strong,document.createTextNode(value));$('profileValues').append(div);}}
function showResults(found){$('cards').replaceChildren();$('matches').hidden=!found.length;for(const m of found){const card=document.createElement('article');card.className='card';for(const [tag,cls,text]of [['span','school',m.institution],['h3','',m.title],['p','',m.summary],['p','why','Waarom deze? Je noemde '+m.matched.map(k=>topics[k].label).join(' en ')+'. Dit onderwerp komt terug in de bronbeschrijving.'],['small','','Toelating en actuele beschikbaarheid: controleer bij de aanbieder.']]){const el=document.createElement(tag);el.className=cls;el.textContent=text;card.append(el);}const link=document.createElement('a');link.textContent='Bekijk op Kies op Maat ↗';link.href=m.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link);$('cards').append(card);}}
function submit(text){if(!ready||!text.trim())return;if(/^(opnieuw|reset|begin opnieuw)[.! ]*$/i.test(text.trim())){reset();return;}if(listening)recognition?.stop();window.speechSynthesis?.cancel();message(text,true);const result=respond(session,text,data);message(result.text);if(result.results)showResults(result.results);else if(session.step!=='results'){$('matches').hidden=true;$('cards').replaceChildren();}$('answer').value='';suggestions();}
$('form').onsubmit=e=>{e.preventDefault();submit($('answer').value);};
function reset(){epoch++;if(recognition){recognition.onresult=null;recognition.abort();}window.speechSynthesis?.cancel();consent=false;listening=false;$('mic').classList.remove('listening');session=createSession();$('chat').replaceChildren();$('answer').value='';$('cards').replaceChildren();$('matches').hidden=true;message('Hoi! Ik ben een regelgestuurde AI-keuzehulp. Ik zoek in een beperkte lijst met echte minoren en geef geen definitief studieadvies. '+firstQuestion);suggestions();$('status').textContent='Nieuw gesprek · eerdere antwoorden gewist';}
$('reset').onclick=reset;$('about').onclick=()=>$('infoDialog').showModal();$('tests').onclick=()=>$('testDialog').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('noVoice').onclick=()=>$('voiceDialog').close();
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'◖ Geluid aan':'◖ Geluid uit';$('sound').setAttribute('aria-pressed',String(sound));if(sound)speak(latest);else window.speechSynthesis?.cancel();};
function startMic(){if(!SR){$('status').textContent='Deze browser biedt geen ondersteunde spraakherkenning. Probeer een browser met SpeechRecognition, of typ.';return;}window.speechSynthesis?.cancel();const current=epoch;recognition=new SR();recognition.lang='nl-NL';recognition.continuous=false;recognition.interimResults=false;recognition.onstart=()=>{listening=true;$('mic').classList.add('listening');$('mic').setAttribute('aria-label','Opname stoppen');$('status').textContent='Ik luister… Klik opnieuw om te stoppen.';};recognition.onresult=e=>{if(current!==epoch)return;$('answer').value=e.results[0][0].transcript;$('status').textContent='Controleer je herkende antwoord en klik op de pijl om te versturen.';$('answer').focus();};recognition.onerror=e=>{$('status').textContent=({ 'not-allowed':'Microfoontoegang geweigerd. Pas je browserrechten aan of typ je antwoord.','no-speech':'Geen spraak gehoord. Probeer opnieuw.','network':'De spraakdienst is niet bereikbaar. Probeer opnieuw of typ.'})[e.error]||'Spraakherkenning gestopt. Probeer opnieuw of typ.';};recognition.onend=()=>{listening=false;$('mic').classList.remove('listening');$('mic').setAttribute('aria-label','Spraak opnemen');if($('status').textContent.startsWith('Ik luister'))$('status').textContent='Opname gestopt. Je kunt opnieuw spreken.';};try{recognition.start();}catch{$('status').textContent='Microfoon kon niet starten. Probeer opnieuw of typ.';}}
$('mic').onclick=()=>{if(!ready)return;if(listening){recognition.stop();return;}if(!SR){startMic();return;}if(!consent){$('voiceDialog').showModal();return;}startMic();};$('allowVoice').onclick=()=>{consent=true;$('voiceDialog').close();startMic();};
$('runTests').onclick=()=>{if(!ready)return;$('testResults').replaceChildren();for(const test of runTests(data)){const box=document.createElement('div');box.className='test-result';box.textContent=(test.pass?'✓ ':'✕ ')+test.name+' — '+(test.pass?'geslaagd':'mislukt');const small=document.createElement('small');small.textContent=test.detail;box.append(small);$('testResults').append(box);}};
try{const res=await fetch('./minors.json');if(!res.ok)throw Error();const body=await res.json();data=body.minors;if(!Array.isArray(data)||!data.length)throw Error();ready=true;$('sourceStatus').textContent=data.length+' minoren · bron: Kies op Maat-index · verzameld 15 oktober 2026 · geen live catalogus';reset();}catch{message('De minorgegevens konden niet worden geladen. Vernieuw de pagina. Zonder bronnen geef ik geen aanbevelingen.');$('status').textContent='Brongegevens ontbreken';$('answer').disabled=true;$('mic').disabled=true;}
window.addEventListener('pagehide',()=>{epoch++;recognition?.abort();window.speechSynthesis?.cancel();session=createSession();});
